import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"repair-station/settings.md","filePath":"repair-station/settings.md"}'),r={name:"repair-station/settings.md"};function i(n,t,s,c,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Every Repair Station setting is edited in <code>/nay</code>, on the <strong>Repair Station</strong> page (scope <code>nay_repair.config</code>). Changes are saved in the database and applied to every player at once. <code>config.lua</code> holds optional starting values: they apply until a setting is changed in <code>/nay</code>, and <strong>Reset</strong> goes back to them.</p><p>The <strong>In /nay</strong> column is the name shown in the panel. The key is the name used by <code>config.lua</code> and the <a href="/nay-lib/api">HTTP API</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enabled</td><td><code>Enabled</code></td><td>on / off</td><td>on</td><td>Turns every station on or off.</td></tr><tr><td>Payment account</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> or <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Where the price is taken from. <code>cash_then_bank</code> uses the bank when cash is short.</td></tr><tr><td>Job discounts</td><td><code>JobDiscounts</code></td><td>list, up to 32</td><td>none</td><td>Discounts for a job from a grade.</td></tr><tr><td>Cooldown (seconds)</td><td><code>CooldownSeconds</code></td><td>seconds, 0 to 3600</td><td>0</td><td>Minimum wait between two repairs of the same player. 0 disables it.</td></tr></tbody></table><p>Entries of <strong>Job discounts</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>text, 1 to 32 characters</td><td>Job name, as in your framework.</td></tr><tr><td>Minimum grade</td><td><code>MinGrade</code></td><td>number, 0 to 100</td><td>Lowest grade that gets the discount.</td></tr><tr><td>Discount (%)</td><td><code>Percent</code></td><td>number, 1 to 100</td><td>Discount in percent. 100 makes the repair free.</td></tr></tbody></table><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Repair services</td><td><code>Services</code></td><td>list, 1 to 8</td><td>Quick fix $250, Body work $400, Full repair $700</td><td>Services offered in every station.</td></tr><tr><td>Price by damage</td><td><code>PriceByDamage</code></td><td>on / off</td><td>on</td><td>Scales the price with the damage of the parts repaired.</td></tr><tr><td>Minimum price (%)</td><td><code>MinPricePercent</code></td><td>number, 0 to 100</td><td>20</td><td>Lowest share of the service price when pricing by damage.</td></tr><tr><td>Refuse undamaged vehicles</td><td><code>RequireDamage</code></td><td>on / off</td><td>on</td><td>Refuses a service when the parts it repairs are intact.</td></tr><tr><td>Blocked vehicle classes</td><td><code>BlockedClasses</code></td><td>list of vehicle classes</td><td>cycles, boats, helicopters, planes, trains</td><td>Vehicle classes refused at the station.</td></tr></tbody></table><p>Entries of <strong>Repair services</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>text, 1 to 32 characters</td><td>Name shown in the repair menu, the history and webhooks.</td></tr><tr><td>Price</td><td><code>Price</code></td><td>number, 0 to 1000000</td><td>Price at full damage, before discounts and the station percentage.</td></tr><tr><td>Duration (seconds)</td><td><code>Seconds</code></td><td>number, 3 to 120</td><td>How long the repair takes.</td></tr><tr><td>Repairs the engine</td><td><code>Engine</code></td><td>on / off</td><td>Includes the fuel tank.</td></tr><tr><td>Repairs the body</td><td><code>Body</code></td><td>on / off</td><td>Includes windows, doors and deformation.</td></tr><tr><td>Repairs the tyres</td><td><code>Tyres</code></td><td>on / off</td><td>Fixes every burst tyre.</td></tr></tbody></table><p>With <code>PriceByDamage</code> on, the price is the service price multiplied by the highest damage of the parts it repairs, never below <code>MinPricePercent</code> and never above 100 percent. Then the station percentage and the job discount apply. With it off, the full price is always charged.</p><p>Entries of <strong>Blocked vehicle classes</strong> have one field, <strong>Class</strong> (<code>Class</code>), picked from the GTA vehicle classes by name.</p><h2 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Stations</td><td><code>Stations</code></td><td>list, up to 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>The stations. Placed with the <a href="/repair-station/stations">station editor</a>.</td></tr></tbody></table><p>Entries are easier to edit with the <a href="/repair-station/stations">station editor</a>, which fills these fields for you:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Identifier</td><td><code>Id</code></td><td>text, 8</td><td>8 characters (0 to 9, a to f), given by the editor. Must be unique.</td></tr><tr><td>Name</td><td><code>Label</code></td><td>text, up to 48 characters</td><td>Shown in the prompt, the history and webhooks. Optional.</td></tr><tr><td>Open</td><td><code>Enabled</code></td><td>on / off</td><td>Closes one station without deleting it.</td></tr><tr><td>Vehicle position</td><td><code>Coords</code></td><td>position and heading</td><td>Where vehicles stop, with the heading.</td></tr><tr><td>Radius (m)</td><td><code>Radius</code></td><td>meters, 1.5 to 6</td><td>How far from the position a vehicle is still in the station.</td></tr><tr><td>Price (%)</td><td><code>PricePercent</code></td><td>number, 0 to 1000</td><td>Percentage applied to every price in this station. 100 keeps the prices.</td></tr><tr><td>Prop model</td><td><code>Prop</code></td><td>text, up to 64 characters</td><td>Prop placed next to the station. Optional.</td></tr><tr><td>Prop position</td><td><code>PropCoords</code></td><td>position and heading</td><td>Where the prop stands. Optional.</td></tr><tr><td>Map blip</td><td><code>Blip</code></td><td>on / off</td><td>Shows this station on the map.</td></tr></tbody></table><h2 id="mechanics" tabindex="-1">Mechanics <a class="header-anchor" href="#mechanics" aria-label="Permalink to &quot;Mechanics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Mechanic jobs</td><td><code>MechanicJobs</code></td><td>list, up to 16</td><td><code>mechanic</code></td><td>Jobs counted as mechanics on duty.</td></tr><tr><td>Mechanics on duty limit</td><td><code>MaxMechanicsOnDuty</code></td><td>number, 0 to 64</td><td>0</td><td>Stations close while this many mechanics or more are on duty. 0 never closes them.</td></tr></tbody></table><p>Entries of <strong>Mechanic jobs</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>text, 1 to 32 characters</td><td>Job name, as in your framework.</td></tr></tbody></table><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Show blips</td><td><code>ShowBlips</code></td><td>on / off</td><td>on</td><td>Shows the stations that have a blip on the map.</td></tr><tr><td>Blip sprite</td><td><code>BlipSprite</code></td><td>blip icon</td><td>446</td><td>Picked from a visual list of icons. Any number can still be typed for a custom blip.</td></tr><tr><td>Blip color</td><td><code>BlipColor</code></td><td>blip colour</td><td>47</td><td>Picked from a visual list of colours.</td></tr><tr><td>Blip scale</td><td><code>BlipScale</code></td><td>0.2 to 2</td><td>0.8</td><td>Size of the blip.</td></tr></tbody></table>',23)])])}const y=e(r,[["render",i]]);export{b as __pageData,y as default};
